      "type": "claim",
      "quote": "The development’s entire annual energy requirement is produced on site in photovoltaic plant in the façades and on the roof with the additional help of a wind energy plant.",
      "gist": "The development produces all its annual energy on-site using solar and wind power."
    },
    {
      "type": "claim",
      "quote": "However, the buildings are not completely autarchic for energy because they are connected to the electricity and gas grids.",
      "gist": "The buildings are not fully energy self-sufficient due to grid connections."
    },
    {
      "type": "number",
      "quote": "Half",
      "gist": "50% of on-site electricity is used directly by tenants."
    },
    {
      "type": "claim",
      "quote": "The rest is conducted to a power-to-gas facility, converted to renewable gas, and stored to produce electricity and heat in winter.",
      "gist": "Remaining on-site electricity is converted to renewable gas and stored for winter use."
    },
    {
      "type": "claim",
      "quote": "The interconnected grids handle seasonal storage of energy generated on the buildings.",
      "gist": "Grids manage seasonal energy storage from the buildings."
    }
  ]
}
